import React from "react";
import { useLocation } from "react-router-dom";

const Result = () => {
  const location = useLocation();
  const query = location.state?.query;

  return (
    <div>
      <h2>Results Page</h2>
      <p>Search Query: {query}</p>
    </div>
  );
};

export default Result;
